  ('e5c4c60b-cc83-54b8-a14d-2dd7036a86d7', null, (select id from public.skills where slug = 'write-g6-precise-language'), null, 'medium',
   $q$Read the paragraph: "Kofi finished his homework. Then he practiced the trumpet. Then he fed the cat. Then he went to bed." Which revision varies the sentence patterns best?$q$, $q$[{"text":"After Kofi finished his homework, he practiced the trumpet. He fed the cat and then went to bed.","is_correct":true},{"text":"Kofi finished his homework, then he practiced the trumpet, then he fed the cat, then he went to bed.","is_correct":false,"misconception_token":"comma-splice-chain"},{"text":"Kofi finished his homework. Then he practiced the trumpet. Next he fed the cat. Then he went to bed.","is_correct":false,"misconception_token":"still-choppy"},{"text":"Kofi finished his homework and practiced the trumpet and fed the cat and went to bed.","is_correct":false,"misconception_token":"and-chain"}]$q$::jsonb, $q$After Kofi finished his homework, he practiced the trumpet. He fed the cat and then went to bed.$q$, $q$This revision opens with "After," then uses a sentence with two verbs, so the sentences no longer all start with "Then." Changing one "Then" to "Next" leaves four short sentences with the same pattern.$q$, 'draft', null)
